INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpyu0019khvugfqefu48', '拼图入门', '提供 2-3 片的大块拼图，示范并引导宝宝将拼图块放入对应位置，锻炼形状匹配与耐心。', '/images/activities/puzzle-starter.svg', 2, NULL, '{COGNITIVE,FINE_MOTOR}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.335', '2026-07-31 14:44:17.335');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpz2001akhvu3oq06g2p', '数字儿歌', '唱数字儿歌（如「一二三四五，上山打老虎」），配合手指动作，建立数感与节奏感。', '/images/activities/counting-songs.svg', 2, NULL, '{LANGUAGE,COGNITIVE}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.342', '2026-07-31 14:44:17.342');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpza001bkhvu5o820nbh', '捉迷藏', '亲子捉迷藏：家长躲起来呼唤宝宝名字，宝宝找到后给予欢呼鼓励，锻炼空间感与安全感。', '/images/activities/hide-and-seek.svg', 2, NULL, '{COGNITIVE,SOCIAL_EMOTIONAL}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.351', '2026-07-31 14:44:17.351');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpzi001ckhvur4crg6z5', '双手对敲', '给宝宝两只手各拿一个小玩具，示范互相敲击发出声音，锻炼双手协调与因果认知。', '/images/activities/knock-toys.svg', 2, NULL, '{FINE_MOTOR}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.358', '2026-07-31 14:44:17.358');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpzq001dkhvu09uk8r4f', '旋拧练习', '提供带旋盖的瓶子或旋钮玩具，示范拧开和拧紧瓶盖，锻炼手腕旋转与手指力量。', '/images/activities/twist-caps.svg', 2, NULL, '{FINE_MOTOR}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.367', '2026-07-31 14:44:17.367');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpzy001ekhvuivfaykmy', '物品用途认知', '指认家中常用物品并演示用途：「杯子用来喝水、灯会亮、电话用来讲话」，建立物品功能概念。', '/images/activities/object-uses.svg', 2, NULL, '{COGNITIVE}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.374', '2026-07-31 14:44:17.374');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zq06001fkhvu646t6mwr', '装扮游戏', '和宝宝玩假装游戏：给娃娃喂饭、哄娃娃睡觉、假装打电话，发展想象力与角色认知。', '/images/activities/pretend-play.svg', 2, NULL, '{SOCIAL_EMOTIONAL,COGNITIVE}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.382', '2026-07-31 14:44:17.382');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zq0e001gkhvuyixuls3o', '向前跳游戏', '在地面贴出线条或格子，示范双脚向前跳出一段距离，鼓励宝宝模仿，锻炼下肢爆发力。', '/images/activities/forward-jump.svg', 3, '地面平整防滑。', '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.39', '2026-07-31 14:44:17.39');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zq0m001hkhvu71lhnx5t', '串珠穿绳', '提供粗绳和大孔珠子，示范将珠子穿到绳上，锻炼手眼协调与专注力。', '/images/activities/bead-threading.svg', 1, '珠子需足够大，防吞食。', '{FINE_MOTOR}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.398', '2026-07-31 14:44:17.398');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpqb0000khvu4j1ersr0', '俯卧抬头', '让宝宝清醒时俯卧在平坦软垫上，在前方放置黑白卡或色彩鲜艳的玩具，轻声呼唤鼓励宝宝抬头。从每次 1~2 分钟开始，随月龄逐渐延长时间。', '/images/activities/tummy-time.svg', 3, '必须在宝宝清醒时进行，全程家长看护；垫软垫；喂奶后 1 小时再进行，避免吐奶。', '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.027', '2026-07-31 14:44:17.027');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpqk0001khvu5h6y3tme', '黑白卡追视', '将黑白对比卡放在宝宝眼前 20~30cm 处，缓慢左右移动，观察宝宝视线是否追随卡片移动。', '/images/activities/contrast-card-tracking.svg', 2, NULL, '{SENSORY}', '{AT_HOME}', '{CARD}', '2026-07-31 14:44:17.036', '2026-07-31 14:44:17.036');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpqq0002khvuh4pc6ylo', '人脸对视互动', '将脸靠近宝宝（20~30cm），微笑、做夸张表情、轻柔呼唤宝宝的名字，观察宝宝是否注视你的脸并给出回应。', '/images/activities/face-to-face.svg', 3, NULL, '{SOCIAL_EMOTIONAL,COGNITIVE}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.042', '2026-07-31 14:44:17.042');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpqw0003khvu1ec4w17i', '声音追踪游戏', '在宝宝身体两侧轻轻摇动响铃或呼唤名字，观察宝宝是否会转头寻找声源，锻炼听觉定位能力。', '/images/activities/sound-tracking.svg', 2, NULL, '{SENSORY}', '{AT_HOME}', '{RATTLE}', '2026-07-31 14:44:17.048', '2026-07-31 14:44:17.048');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpr20004khvuvxb6fa5r', '婴儿抚触按摩', '洗澡后或睡前，用温水洗净双手、涂少量润肤油，轻柔按摩宝宝的四肢、背部与腹部（避开脐部），配合轻柔的说话声。', '/images/activities/baby-massage.svg', 1, '室内温度适宜，手法轻柔；观察宝宝反应，抗拒或哭闹时立即停止。', '{SENSORY}', '{BEDTIME}', '{OIL}', '2026-07-31 14:44:17.054', '2026-07-31 14:44:17.054');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpra0005khvu2e4sgikp', '轻柔被动操', '宝宝仰卧时，家长握住宝宝手腕与脚踝，缓慢做伸屈、外展等被动运动，配合轻柔的口令和儿歌节奏。', '/images/activities/passive-exercise.svg', 2, '动作缓慢轻柔，宝宝抗拒时不勉强。', '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.063', '2026-07-31 14:44:17.063');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpri0006khvup4zt1im6', '对话互动', '随时随地与宝宝对话：描述正在做的事情，等待宝宝发出声音后模仿回应，形成你来我往的交流。', '/images/activities/conversation-interaction.svg', 3, NULL, '{LANGUAGE}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.071', '2026-07-31 14:44:17.071');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zprs0007khvu1r3j8je1', '听儿歌磨耳朵', '播放节奏舒缓的儿歌或英文童谣，抱着宝宝轻轻摇晃，观察宝宝对音乐的反应，可在睡前作为固定仪式。', '/images/activities/music-morning.svg', 2, '音量适中，单次不超过 15~20 分钟。', '{LANGUAGE,SENSORY}', '{BEDTIME}', '{NONE}', '2026-07-31 14:44:17.081', '2026-07-31 14:44:17.081');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zps20008khvub0oayxz4', '抓握练习', '将摇铃或软玩具轻轻触碰宝宝手心，刺激抓握反射；也可让宝宝抓住家长的手指，练习握力。', '/images/activities/grasp-practice.svg', 2, NULL, '{FINE_MOTOR}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.091', '2026-07-31 14:44:17.091');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpsa0009khvutwp8rbnt', '摇铃摇动', '示范摇动响铃发出声音，鼓励宝宝自己抓握摇铃并摇晃，感受「摇一摇就有声音」的因果联系。', '/images/activities/rattle-shake.svg', 2, NULL, '{FINE_MOTOR,COGNITIVE}', '{AT_HOME}', '{RATTLE}', '2026-07-31 14:44:17.098', '2026-07-31 14:44:17.098');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpsg000akhvubi67ef0g', '拉坐练习', '宝宝仰卧，家长握住宝宝双手，缓慢拉起至坐姿再缓慢放下，锻炼颈部与躯干力量。约 3 个月后开始。', '/images/activities/pull-to-sit.svg', 2, '须待宝宝能自主控制头部后再进行；动作缓慢，若头部后仰立即停止。', '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.104', '2026-07-31 14:44:17.104');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpso000bkhvunhmjujmm', '翻身辅助', '宝宝仰卧时，家长轻推宝宝一侧肩膀与臀部，辅助完成仰卧到侧卧再到俯卧的翻身动作，左右交替进行。', '/images/activities/rolling-assist.svg', 3, '动作轻柔，在软垫上进行。', '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.112', '2026-07-31 14:44:17.112');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpsu000ckhvujnc7km32', '躲猫猫游戏', '用手或手帕遮住自己的脸，再突然打开并发出「喵~」的声音，观察宝宝的反应，等待宝宝主动发起互动。', '/images/activities/peekaboo.svg', 3, NULL, '{SOCIAL_EMOTIONAL,COGNITIVE}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.119', '2026-07-31 14:44:17.119');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpt2000dkhvuh0sqhc5o', '伸手抓玩具', '在宝宝伸手可及的范围内悬挂或放置色彩鲜艳的玩具，鼓励宝宝主动伸手抓取，锻炼手眼协调。', '/images/activities/reach-and-grab.svg', 3, NULL, '{FINE_MOTOR,COGNITIVE}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.127', '2026-07-31 14:44:17.127');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpta000ekhvu339cge1q', '照镜子游戏', '抱着宝宝照镜子，指着镜中的宝宝和自己说出名字，做表情互动，观察宝宝对镜像的好奇与反应。', '/images/activities/mirror-play.svg', 2, NULL, '{SOCIAL_EMOTIONAL,COGNITIVE}', '{AT_HOME}', '{MIRROR}', '2026-07-31 14:44:17.135', '2026-07-31 14:44:17.135');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpti000fkhvuyq8bktou', '咿呀学语回应', '宝宝发出咿咿呀呀的声音时，立即模仿回应并加入新的音节，拉长声调，鼓励宝宝继续发声交流。', '/images/activities/babble-response.svg', 3, NULL, '{LANGUAGE}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.142', '2026-07-31 14:44:17.142');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zptq000gkhvue046xm3d', '靠坐练习', '用靠垫支撑或让宝宝坐在家长怀中，练习头部控制与躯干稳定，从短时间开始逐渐延长。', '/images/activities/supported-sitting.svg', 2, '靠垫支撑到位，时间由短到长，宝宝疲劳即休息。', '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.15', '2026-07-31 14:44:17.15');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpty000hkhvukd6nl6wq', '物品传递', '给宝宝一个软积木或玩具，示范从一只手换到另一只手，鼓励宝宝模仿传递动作，锻炼双手协作。', '/images/activities/object-transfer.svg', 2, NULL, '{FINE_MOTOR}', '{AT_HOME}', '{BLOCK}', '2026-07-31 14:44:17.159', '2026-07-31 14:44:17.159');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpu6000ikhvujfab9soz', '布书绘本翻看', '抱着宝宝翻看布书或硬页绘本，指着图案说出名称，用夸张的语气和表情讲故事，培养阅读兴趣。', '/images/activities/book-reading.svg', 1, NULL, '{COGNITIVE,LANGUAGE}', '{BEDTIME}', '{PICTURE_BOOK}', '2026-07-31 14:44:17.167', '2026-07-31 14:44:17.167');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpuc000jkhvut423qbb1', '蹬自行车运动', '宝宝仰卧，家长握住宝宝脚踝做轻柔的蹬自行车动作，配合儿歌节奏，锻炼下肢力量与灵活性。', '/images/activities/bicycle-kicks.svg', 2, NULL, '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.172', '2026-07-31 14:44:17.172');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpui000kkhvuxave88u7', '嗅觉探索', '将苹果、香蕉等安全水果凑近宝宝鼻前（不接触），让宝宝闻气味，同时说出水果名称，丰富感官体验。', '/images/activities/smell-exploration.svg', 1, '水果仅用于闻嗅，不让宝宝啃咬。', '{SENSORY}', '{AT_HOME}', '{FRUIT}', '2026-07-31 14:44:17.179', '2026-07-31 14:44:17.179');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpuo000lkhvuz3ecu9q9', '模仿表情游戏', '面对宝宝缓慢做吐舌头、张大嘴、皱眉等表情，停留几秒，观察宝宝是否会模仿你的表情。', '/images/activities/expression-mimicry.svg', 2, NULL, '{SOCIAL_EMOTIONAL}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.184', '2026-07-31 14:44:17.184');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpuu000mkhvusqgc1y0o', '脚底触觉游戏', '用不同材质（毛巾、软刷、手掌）轻轻触碰宝宝的脚底和小腿，观察宝宝的反应，丰富触觉体验。', '/images/activities/sole-touch.svg', 2, NULL, '{SENSORY}', '{AT_HOME}', '{TOWEL}', '2026-07-31 14:44:17.19', '2026-07-31 14:44:17.19');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpv0000nkhvuyfunm63u', '追视移动物体', '用色彩鲜艳的玩具在宝宝眼前缓慢画弧线移动，观察宝宝视线是否跟随，锻炼眼球运动与注意力。', '/images/activities/moving-object-tracking.svg', 2, NULL, '{COGNITIVE,SENSORY}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.196', '2026-07-31 14:44:17.196');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpv6000okhvupp3m98g0', '独坐练习', '让宝宝不靠支撑独自坐稳，前方放置玩具吸引伸手，练习躯干平衡；周围铺软垫防倾倒。', '/images/activities/sitting-independently.svg', 2, '周围铺软垫，宝宝疲劳即休息。', '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.203', '2026-07-31 14:44:17.203');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpvc000pkhvuu2fwgnzy', '爬行游戏', '在宝宝前方滚动球或放置玩具，鼓励宝宝匍匐爬行、手膝爬行去够取，练习四肢协调。', '/images/activities/crawling-game.svg', 3, NULL, '{GROSS_MOTOR}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.208', '2026-07-31 14:44:17.208');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpvi000qkhvuczigtu83', '物体恒存游戏', '当着宝宝的面用布或杯子盖住玩具，问「玩具去哪儿了？」鼓励宝宝掀开寻找，理解看不见的东西依然存在。', '/images/activities/object-permanence.svg', 2, NULL, '{COGNITIVE}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.214', '2026-07-31 14:44:17.214');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpvo000rkhvu5ei8ns3h', '捏取练习', '提供小块安全食物或小玩具，示范用拇指和食指捏起，锻炼精细抓握与手眼协调。', '/images/activities/pincer-grasp.svg', 2, '小物件需防呛噎，全程看护。', '{FINE_MOTOR}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.22', '2026-07-31 14:44:17.22');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpvs000skhvugnoirpzd', '扶站练习', '扶着宝宝腋下或让宝宝扶着沙发站立，练习腿部力量与平衡，时间由短到长。', '/images/activities/standing-support.svg', 2, NULL, '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.224', '2026-07-31 14:44:17.224');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpvy000tkhvucqkiwoo8', '巡航练习', '让宝宝扶着家具边缘横向移动，家长在旁保护，逐渐增加移动距离。', '/images/activities/cruising.svg', 2, '家具稳固，移开危险物品。', '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.23', '2026-07-31 14:44:17.23');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpw2000ukhvu29wtn55i', '拍手游戏', '边唱拍手歌边示范拍手，引导宝宝模仿拍手动作，锻炼节奏感与模仿能力。', '/images/activities/clapping-game.svg', 3, NULL, '{SOCIAL_EMOTIONAL,GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.234', '2026-07-31 14:44:17.234');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpw8000vkhvugjw66zan', '再见挥手', '出门或家人离开时，边挥手边说「拜拜」，引导宝宝模仿挥手告别，理解告别礼仪。', '/images/activities/bye-bye-wave.svg', 2, NULL, '{SOCIAL_EMOTIONAL}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.24', '2026-07-31 14:44:17.24');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpwe000wkhvujmhs2foj', '指认身体部位', '问「宝宝的鼻子在哪里？」引导宝宝指认五官，再扩展到手脚四肢，锻炼认知与语言理解。', '/images/activities/body-parts.svg', 3, NULL, '{COGNITIVE,LANGUAGE}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.246', '2026-07-31 14:44:17.246');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpwh000xkhvujwmb7uwb', '叠积木', '示范将积木一块块叠高，鼓励宝宝模仿，从叠两块逐渐到多块，锻炼精细动作与专注力。', '/images/activities/block-stacking.svg', 2, NULL, '{FINE_MOTOR,COGNITIVE}', '{AT_HOME}', '{BLOCK}', '2026-07-31 14:44:17.25', '2026-07-31 14:44:17.25');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpwm000ykhvu2lv7wqnj', '翻书页', '鼓励宝宝自己翻动硬页书的书页，边翻边说出内容，锻炼手指灵活与阅读兴趣。', '/images/activities/page-turning.svg', 1, NULL, '{FINE_MOTOR}', '{AT_HOME}', '{PICTURE_BOOK}', '2026-07-31 14:44:17.254', '2026-07-31 14:44:17.254');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpws000zkhvup6z9856r', '用杯子喝水', '用带手柄的学饮杯装少量水，鼓励宝宝双手捧杯自己喝，锻炼手口协调与自理能力。', '/images/activities/cup-drinking.svg', 2, '少量水防呛，水温适宜。', '{FINE_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.26', '2026-07-31 14:44:17.26');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpwy0010khvusokyxjkn', '独走练习', '在宝宝前方张开双臂引导独走，从迈出两步到几步，逐步增加距离，练习平衡与信心。', '/images/activities/walking-practice.svg', 3, '平整地面，周围无尖角。', '{GROSS_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.266', '2026-07-31 14:44:17.266');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpx40011khvu9jefuzwy', '指物表达', '当宝宝想要某物时，鼓励宝宝用手指指向并说出名称，而不是立即代劳，培养语言表达。', '/images/activities/pointing-request.svg', 3, NULL, '{LANGUAGE}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.272', '2026-07-31 14:44:17.272');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpxa0012khvuhifvs9be', '模仿家务', '给宝宝小抹布、小扫把，让宝宝模仿大人擦桌子、扫地，培养参与感与自理意识。', '/images/activities/housework-mimic.svg', 2, NULL, '{SOCIAL_EMOTIONAL}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.278', '2026-07-31 14:44:17.278');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpxg0013khvuh9hf5vl5', '跑跳游戏', '在户外或开阔空间和宝宝玩追逐跑、踢球、双脚跳游戏，锻炼大肌肉群与协调能力。', '/images/activities/run-jump-play.svg', 3, NULL, '{GROSS_MOTOR}', '{OUTDOOR}', '{BALL}', '2026-07-31 14:44:17.284', '2026-07-31 14:44:17.284');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpxo0014khvu6mfxdy63', '说短句', '日常中扩展宝宝的表达：宝宝说「水」，家长回应「宝宝要喝水」，引导说出更完整的句子。', '/images/activities/short-phrases.svg', 3, NULL, '{LANGUAGE}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.293', '2026-07-31 14:44:17.293');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpxy0015khvupfi9k1e2', '颜色形状认知', '用积木或卡片教认颜色和形状，玩「把红色的积木给妈妈」游戏，锻炼分类与指令理解。', '/images/activities/color-shapes.svg', 2, NULL, '{COGNITIVE}', '{AT_HOME}', '{BLOCK}', '2026-07-31 14:44:17.302', '2026-07-31 14:44:17.302');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpy60016khvueopcgrwh', '穿脱衣物', '鼓励宝宝自己脱袜子、脱鞋、解开魔术贴，逐步练习穿脱简单衣物，培养自理能力。', '/images/activities/dress-practice.svg', 2, '给予充足时间，不催促。', '{FINE_MOTOR}', '{AT_HOME}', '{NONE}', '2026-07-31 14:44:17.311', '2026-07-31 14:44:17.311');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpye0017khvuxivy23z0', '社交游戏', '安排与其他小朋友玩平行游戏或简单轮流游戏，学习分享、等待与社交互动。', '/images/activities/social-play.svg', 2, NULL, '{SOCIAL_EMOTIONAL}', '{OUTDOOR}', '{TOY}', '2026-07-31 14:44:17.319', '2026-07-31 14:44:17.319');
INSERT INTO public."Activity" (id, title, description, "imageUrl", "dailyTargetCount", "safetyTip", "skillAreas", scenarios, props, "createdAt", "updatedAt") VALUES ('cms91zpym0018khvur3teao57', '涂鸦画画', '提供粗蜡笔和大纸，让宝宝自由涂鸦，不纠正「画得像不像」，保护创造力与握笔兴趣。', '/images/activities/scribble-drawing.svg', 2, '使用无毒可水洗蜡笔。', '{FINE_MOTOR}', '{AT_HOME}', '{TOY}', '2026-07-31 14:44:17.326', '2026-07-31 14:44:17.326');
